package net.civeira.phylax.feature.identity.tenantloginprovider.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.tenantloginprovider.domain.TenantLoginProvider;
import net.civeira.phylax.feature.identity.tenantloginprovider.domain.valueobject.SamlIdpMetadataUrlVO;

class SamlIdpMetadataUrlValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of saml idp metadata url of tenant login provider")
  void test_saml_idp_metadata_url_value_holder_assign_plain_value() {
    Object holder = new Object();
    SamlIdpMetadataUrlValueHolder<Object> value = new SamlIdpMetadataUrlValueHolder<>(holder);
    Assertions.assertSame(holder, value.samlIdpMetadataUrl("one"),
        "Setters must return the holder");
    Assertions.assertTrue(value.getSamlIdpMetadataUrlValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getSamlIdpMetadataUrl().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.samlIdpMetadataUrlNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getSamlIdpMetadataUrlValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getSamlIdpMetadataUrl().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of saml idp metadata url of tenant login provider")
  void test_saml_idp_metadata_url_value_holder_assign_value_object() {
    Object holder = new Object();
    SamlIdpMetadataUrlValueHolder<Object> value = new SamlIdpMetadataUrlValueHolder<>(holder);
    SamlIdpMetadataUrlVO vo = SamlIdpMetadataUrlVO.from("one");
    Assertions.assertFalse(value.getSamlIdpMetadataUrlValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.samlIdpMetadataUrl(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getSamlIdpMetadataUrlValue().orElseThrow());
    Assertions.assertSame(holder, value.samlIdpMetadataUrl(Optional.empty()));
    Assertions.assertFalse(value.getSamlIdpMetadataUrlValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.samlIdpMetadataUrl(Optional.of(vo)));
    Assertions.assertSame(vo, value.getSamlIdpMetadataUrlValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of saml idp metadata url of tenant login provider against the original")
  void test_saml_idp_metadata_url_value_holder_read() {
    Object holder = new Object();
    SamlIdpMetadataUrlValueHolder<Object> value = new SamlIdpMetadataUrlValueHolder<>(holder);
    SamlIdpMetadataUrlVO vo = SamlIdpMetadataUrlVO.from("one");
    SamlIdpMetadataUrlVO other = SamlIdpMetadataUrlVO.from("one");
    TenantLoginProvider original = Mockito.mock(TenantLoginProvider.class);
    Mockito.when(original.getSamlIdpMetadataUrlValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readSamlIdpMetadataUrl(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readSamlIdpMetadataUrl(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.samlIdpMetadataUrl(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readSamlIdpMetadataUrl(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readSamlIdpMetadataUrl(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of saml idp metadata url of tenant login provider")
  void test_saml_idp_metadata_url_value_holder_unset() {
    Object holder = new Object();
    SamlIdpMetadataUrlValueHolder<Object> value = new SamlIdpMetadataUrlValueHolder<>(holder);
    SamlIdpMetadataUrlVO vo = SamlIdpMetadataUrlVO.from("one");
    value.samlIdpMetadataUrl(vo);
    Assertions.assertSame(holder,
        value.unsetSamlIdpMetadataUrlIfMatches("samlIdpMetadataUrl_other"));
    Assertions.assertTrue(value.getSamlIdpMetadataUrlValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetSamlIdpMetadataUrlIfMatches("samlIdpMetadataUrl"));
    Assertions.assertFalse(value.getSamlIdpMetadataUrlValue().isPresent(),
        "The field name must clear the value");
    value.samlIdpMetadataUrl(vo);
    Assertions.assertSame(holder, value.unsetSamlIdpMetadataUrl());
    Assertions.assertFalse(value.getSamlIdpMetadataUrlValue().isPresent(),
        "Unset must clear the value");
  }
}
